'use strict';
/* Grushak y Garra Negra de frente y de espaldas (12/11, de la lista "haz todo eso": "Grushak y Garra Negra de frente/espaldas").
   PixelLab: una vista de frente y otra de espaldas hechas desde su dibujo de costado (create_image_pro_flash con el de costado
   como estilo) y animadas caminando en 8 cuadros (animate_image); achicadas a la altura de su vista de costado, con la paleta
   de esa vista y los pies a la misma altura (hojas de 100x100 por cuadro).
   Caminan de frente cuando van para abajo y de espaldas cuando van para arriba; de costado, como siempre. La vista sale de
   hacia dónde se mueven de verdad en cada cuadro (si se quedan quietos, vuelven a estar parados), igual que los del coliseo.
   Además, dos animaciones nuevas de Garra Negra (PixelLab, desde su dibujo de costado): AULLIDO (levanta la cabeza y aúlla
   con los brazos abiertos) y SALTO (se agacha, salta con las garras arriba y cae golpeando el piso); las usa
   ck_jefes_especiales.js para el aullido que te pone lento y el salto.
   Borrar su línea de index.html los deja sólo de costado (y los especiales usan las animaciones de antes). */
(function () {
  if (typeof MainGameScene === 'undefined') return;
  const P = MainGameScene.prototype;
  const TIPOS = { orc_warlord: 1, werebear_jefe: 1 };
  const ARTE = {
    orc_warlord_walk_front: 'data:image/png;base64,',
    orc_warlord_walk_back: 'data:image/png;base64,',
    werebear_jefe_walk_front: 'data:image/png;base64,',
    werebear_jefe_walk_back: 'data:image/png;base64,',
    werebear_jefe_aullido: 'data:image/png;base64,',
    werebear_jefe_salto: 'data:image/png;base64,'
  };
  const pr0 = P.preloadRoster;
  P.preloadRoster = function () {
    const r = pr0.apply(this, arguments);
    try { Object.keys(ARTE).forEach(k => { if (!this.textures.exists(k)) this.load.spritesheet(k, ARTE[k], { frameWidth: 100, frameHeight: 100 }); }); } catch (e) {}
    return r;
  };
  const cra0 = P.createRosterAnimations;
  P.createRosterAnimations = function () {
    const r = cra0.apply(this, arguments);
    try {
      Object.keys(ARTE).forEach(k => {
        if (this.anims.exists(k) || !this.textures.exists(k)) return;
        const n = this.textures.get(k).frameTotal - 1;
        const walk = /_walk_/.test(k);
        this.anims.create({ key: k, frames: this.anims.generateFrameNumbers(k, { start: 0, end: n - 1 }), frameRate: walk ? 10 : (/salto/.test(k) ? 9 : 11), repeat: walk ? -1 : 0 });
      });
    } catch (e) {}
    return r;
  };
  // el juego vuelve a pedir <tipo>_walk en cada paso: si ya va de frente o de espaldas, no se corta
  const play0 = Phaser.GameObjects.Sprite.prototype.play;
  Phaser.GameObjects.Sprite.prototype.play = function (key, ignoreIfPlaying) {
    if (TIPOS[this.type] && typeof key === 'string' && key === this.type + '_walk') {
      const k = this.anims && this.anims.currentAnim && this.anims.currentAnim.key;
      if (k === key + '_front' || k === key + '_back') return this;
    }
    return play0.apply(this, arguments);
  };
  const vistas = S => S.enemies.getChildren().forEach(e => {
    if (!TIPOS[e.type] || !e.active || e.isDead || !e.body || e._ckEsp) return;
    const k = e.anims.currentAnim && e.anims.currentAnim.key, t = e.type;
    if (k !== t + '_walk' && k !== t + '_walk_front' && k !== t + '_walk_back') return;
    const vx = e.body.velocity.x, vy = e.body.velocity.y, ax = Math.abs(vx), ay = Math.abs(vy), lado = k === t + '_walk';
    if (ax < 8 && ay < 8) { if (!lado && !e.isAttacking && S.anims.exists(t + '_idle')) play0.call(e, t + '_idle', true); return; }
    let q = t + '_walk';
    if (ay > ax * (lado ? 1.3 : 0.9)) q = t + (vy > 0 ? '_walk_front' : '_walk_back');
    if (q !== k && S.anims.exists(q)) play0.call(e, q, true);
    if (q !== t + '_walk') e.setFlipX(false); else if (ax > 5) e.setFlipX(vx < 0);
  });
  const ue0 = P.updateEnemies;
  P.updateEnemies = function () {
    const r = ue0.apply(this, arguments);
    try { if (this.enemies) vistas(this); } catch (e) {}
    return r;
  };
  window.CK_JEFES_VISTAS = { TIPOS };
})();
